import { describe, expect, it } from "vitest";
import { resolveTracingProvider } from "../src/observability/create-tracer-from-env.js";

describe("resolveTracingProvider", () => {
  it("defaults to langfuse when unset", () => {
    expect(resolveTracingProvider({})).toBe("langfuse");
  });

  it("selects configured providers", () => {
    expect(resolveTracingProvider({ TRACING_PROVIDER: "traceroot" })).toBe("traceroot");
    expect(resolveTracingProvider({ TRACING_PROVIDER: "Langfuse" })).toBe("langfuse");
  });

  it("treats disable aliases as noop", () => {
    for (const value of ["noop", "none", "off", "false", "disabled"]) {
      expect(resolveTracingProvider({ TRACING_PROVIDER: value })).toBe("noop");
    }
  });

  it("falls back to noop for unknown values", () => {
    expect(resolveTracingProvider({ TRACING_PROVIDER: "unknown" })).toBe("noop");
  });
});

import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-proto";
import { NodeSDK } from "@opentelemetry/sdk-node";
import { BatchSpanProcessor } from "@opentelemetry/sdk-trace-base";
import {
  resolveTraceRootGitContext,
  warnIfTraceRootGitContextIncomplete,
} from "./traceroot-git-context.js";
import { TraceRootGitSpanProcessor } from "./traceroot-span-processor.js";
import type { TracingBackend } from "./types.js";

const DEFAULT_HOST = "https://app.traceroot.ai";

export function createTraceRootBackend(env: NodeJS.ProcessEnv = process.env): TracingBackend | null {
  const apiKey = env.TRACEROOT_API_KEY?.trim();
  if (!apiKey) {
    return null;
  }

  const gitContext = resolveTraceRootGitContext(env);
  warnIfTraceRootGitContextIncomplete(gitContext);

  const host = (env.TRACEROOT_HOST_URL?.trim() || DEFAULT_HOST).replace(/\/$/, "");
  const exporter = new OTLPTraceExporter({
    url: `${host}/api/v1/public/traces`,
    headers: {
      Authorization: `Bearer ${apiKey}`,
    },
  });
  const spanProcessor = new TraceRootGitSpanProcessor(
    new BatchSpanProcessor(exporter),
    gitContext.gitRepo,
    gitContext.gitRef,
  );
  const sdk = new NodeSDK({
    spanProcessors: [spanProcessor],
  });

  return {
    provider: "traceroot",
    start() {
      sdk.start();
    },
    async flush() {
      try {
        await spanProcessor.forceFlush();
      } catch {}
    },
    async shutdown() {
      try {
        await sdk.shutdown();
      } catch {}
    },
  };
}

import { NoopDailyBriefingTracer, type DailyBriefingTracer } from "./daily-briefing-tracer.js";
import { OtelDailyBriefingTracer } from "./otel-daily-briefing-tracer.js";
import { createLangfuseBackend } from "./providers/langfuse.js";
import { createTraceRootBackend } from "./providers/traceroot.js";
import type { TracingBackend, TracingProviderName } from "./providers/types.js";

export function resolveTracingProvider(env: NodeJS.ProcessEnv = process.env): TracingProviderName | "noop" {
  const raw = (env.TRACING_PROVIDER ?? "langfuse").trim().toLowerCase();
  if (raw === "langfuse" || raw === "traceroot") {
    return raw;
  }
  if (raw === "noop" || raw === "none" || raw === "off" || raw === "false" || raw === "disabled") {
    return "noop";
  }
  return "noop";
}

function createBackend(provider: TracingProviderName, env: NodeJS.ProcessEnv): TracingBackend | null {
  if (provider === "langfuse") {
    return createLangfuseBackend(env);
  }
  return createTraceRootBackend(env);
}

export function createDailyBriefingTracerFromEnv(env: NodeJS.ProcessEnv = process.env): DailyBriefingTracer {
  const provider = resolveTracingProvider(env);
  if (provider === "noop") {
    return new NoopDailyBriefingTracer();
  }

  try {
    const backend = createBackend(provider, env);
    if (!backend) {
      return new NoopDailyBriefingTracer();
    }
    backend.start();
    return new OtelDailyBriefingTracer(backend);
  } catch {
    return new NoopDailyBriefingTracer();
  }
}

/** @deprecated Use createDailyBriefingTracerFromEnv() with TRACING_PROVIDER=langfuse */
export function createLangfuseDailyBriefingTracerFromEnv(env: NodeJS.ProcessEnv = process.env): DailyBriefingTracer {
  return createDailyBriefingTracerFromEnv({
    ...env,
    TRACING_PROVIDER: "langfuse",
  });
}

